using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

public sealed class AppHostFixture : IAsyncLifetime
{
    private DistributedApplication? _app;

    public DistributedApplication App => _app ?? throw new InvalidOperationException("App not started.");

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await builder.BuildAsync();
        var resourceNotification = _app.CreateResourceNotificationService();
        await _app.StartAsync();

        // Wait for all resources to be running.
        await resourceNotification.WaitForResourceHealthyAsync("webfrontend", TimeSpan.FromSeconds(60));
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

[CollectionDefinition(Name)]
public class AppHostCollection : ICollectionFixture<AppHostFixture>
{
    public const string Name = "AppHost";
}

using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

[Trait("Category", "Startup")]
public sealed class StartupTests
{
    [Fact]
    public async Task AppHost_Starts_Successfully()
    {
        // Arrange & Act
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        // Assert
        Assert.Equal("Running", app.Services.GetRequiredService<IHostApplicationLifetime>() is not null ? "Running" : "Failed");

        await app.StopAsync();
    }

    [Fact]
    public async Task AppHost_Exposes_Expected_Resources()
    {
        // Arrange
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var resourceNotification = app.CreateResourceNotificationService();
        await app.StartAsync();

        // Act & Assert – verify the app model has at least one resource
        var model = app.Services.GetRequiredService<Aspire.Hosting.DistributedApplicationModel>();
        Assert.NotEmpty(model.Resources);

        await app.StopAsync();
    }
}

using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

[Trait("Category", "Resources")]
public sealed class ResourceTests
{
    [Fact]
    public async Task All_Resources_Reach_Running_State()
    {
        // Arrange
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var resourceNotification = app.CreateResourceNotificationService();
        await app.StartAsync();

        // Act & Assert
        var model = app.Services.GetRequiredService<Aspire.Hosting.DistributedApplicationModel>();
        foreach (var resource in model.Resources)
        {
            // Each resource should eventually reach a running/healthy state.
            await resourceNotification.WaitForResourceReadyAsync(resource.Name, TimeSpan.FromSeconds(30));
        }

        await app.StopAsync();
    }
}

using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

[Trait("Category", "Agent")]
public sealed class AgentBehaviorTests
{
    [Fact]
    public async Task Agent_Responds_To_Prompt()
    {
        // Arrange
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var resourceNotification = app.CreateResourceNotificationService();
        await app.StartAsync();

        // Act – send a basic prompt to the agent endpoint
        using var client = app.CreateHttpClient("webfrontend");
        var response = await client.PostAsJsonAsync("/agent/chat", new { prompt = "Hello" });

        // Assert
        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadAsStringAsync();
        Assert.False(string.IsNullOrWhiteSpace(body), "Agent should return a non-empty response.");

        await app.StopAsync();
    }

    [Fact]
    public async Task Agent_Uses_Tools_When_Appropriate()
    {
        // Arrange
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var resourceNotification = app.CreateResourceNotificationService();
        await app.StartAsync();

        // Act – send a prompt that should trigger tool usage
        using var client = app.CreateHttpClient("webfrontend");
        var response = await client.PostAsJsonAsync("/agent/chat", new
        {
            prompt = "What is the current date and time?"
        });

        // Assert
        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadAsStringAsync();
        Assert.False(string.IsNullOrWhiteSpace(body));

        await app.StopAsync();
    }
}

