using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

[Trait("Category", "Agent")]
public sealed class AgentBehaviorTests
{
    [Fact]
    public async Task Agent_Responds_To_Prompt()
    {
        // Arrange
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var resourceNotification = app.CreateResourceNotificationService();
        await app.StartAsync();

        // Act – send a basic prompt to the agent endpoint
        using var client = app.CreateHttpClient("webfrontend");
        var response = await client.PostAsJsonAsync("/agent/chat", new { prompt = "Hello" });

        // Assert
        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadAsStringAsync();
        Assert.False(string.IsNullOrWhiteSpace(body), "Agent should return a non-empty response.");

        await app.StopAsync();
    }

    [Fact]
    public async Task Agent_Uses_Tools_When_Appropriate()
    {
        // Arrange
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var resourceNotification = app.CreateResourceNotificationService();
        await app.StartAsync();

        // Act – send a prompt that should trigger tool usage
        using var client = app.CreateHttpClient("webfrontend");
        var response = await client.PostAsJsonAsync("/agent/chat", new
        {
            prompt = "What is the current date and time?"
        });

        // Assert
        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadAsStringAsync();
        Assert.False(string.IsNullOrWhiteSpace(body));

        await app.StopAsync();
    }
}

